        ImportConnectionErrorReason: "auth_failed" | "site_not_found" | "project_not_found" | "jql_invalid" | "unreachable" | "dns_failed" | "tls_failed" | "blocked_address" | "invalid_url" | "rate_limited" | "too_many_issues";
