            config_version: number;
            grant_version: number;
            /** Format: uuid */
            actor_id: string;
            state: components["schemas"]["RunState"];
            generation: number;
            reconciliation_required: boolean;
            /** Format: uuid */
            retry_of?: string;
            reason: string;
